trait Pricing {                                  // Strategy
    fn price(&self, qty: f64) -> f64;
}

struct Wholesale { discount: f64 }               // ConcreteStrategy
impl Pricing for Wholesale {
    fn price(&self, qty: f64) -> f64 { qty * (1.0 - self.discount) }
}

struct Checkout { strategy: Box<dyn Pricing> }   // Context, chosen at run time

impl Checkout {
    fn total(&self, qty: f64) -> f64 { self.strategy.price(qty) }
}

