trait Pricing { fn price(&self, qty: f64) -> f64; }

fn total<P: Pricing>(pricing: &P, qty: f64) -> f64 {   // static dispatch
    pricing.price(qty)                                  // monomorphised, inlined
}

fn total_with(pricing: impl Fn(f64) -> f64, qty: f64) -> f64 { pricing(qty) }

